<?php namespace App\Filament\Resources;use App\Filament\Resources\UpbringingTaskResource\Pages;use App\Models\UpbringingTask;use Illuminate\Support\Facades\DB;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;class UpbringingTaskResource extends Resource{protected static ?string $model=UpbringingTask::class;protected static ?string $navigationGroup='Воспитательная работа';protected static ?string $navigationLabel='Поручения';protected static ?string $pluralModelLabel='Поручения';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('assigned_to')->label('Ответственный')->options(fn()=>DB::table('users')->where('is_active',1)->orderBy('name')->pluck('name','id'))->searchable()->required(),Forms\Components\TextInput::make('title')->label('Поручение')->required(),Forms\Components\Textarea::make('description')->label('Описание')->columnSpan('full'),Forms\Components\Select::make('priority')->label('Приоритет')->options(['low'=>'Низкий','normal'=>'Обычный','high'=>'Высокий'])->required(),Forms\Components\DatePicker::make('due_on')->label('Срок'),Forms\Components\Select::make('status')->label('Статус')->options(['new'=>'Новое','in_progress'=>'В работе','done'=>'Выполнено'])->required(),Forms\Components\Textarea::make('result')->label('Результат')->columnSpan('full')])->columns(2);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('title')->label('Поручение')->searchable(),Tables\Columns\TextColumn::make('assigned_to')->label('Ответственный')->formatStateUsing(fn($s)=>DB::table('users')->where('id',$s)->value('name')?:'—'),Tables\Columns\BadgeColumn::make('priority')->label('Приоритет'),Tables\Columns\TextColumn::make('due_on')->label('Срок')->date('d.m.Y'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->actions([Tables\Actions\EditAction::make()->label('Изменить')]);}public static function getPages():array{return['index'=>Pages\ListUpbringingTasks::route('/'),'create'=>Pages\CreateUpbringingTask::route('/create'),'edit'=>Pages\EditUpbringingTask::route('/{record}/edit')];}public static function canViewAny():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}public static function canCreate():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.manage'));}public static function canEdit($record):bool{return static::canCreate();}public static function canDelete($record):bool{return false;}}